/* Reusable TechTag component with optional icon lookup */
function TechTag({ name, className = 'tech-tag' }) {
  const icon = TECH_ICONS[name];
  const color = TECH_COLORS[name];
  return (
    <span
      className={className}
      style={color ? { '--tag-color': color, borderColor: `${color}55`, color: color } : undefined}
    >
      {icon && (
        <span className="tech-tag-icon" aria-hidden="true" style={color ? { color } : undefined}>{icon}</span>
      )}
      {name}
    </span>
  );
}

/* ════════════════════════════════════════
   TYPED TEXT HOOK
════════════════════════════════════════ */
function useTyped(strings, speed = 60, pause = 1800) {
  const [display, setDisplay] = useState('');
  const [strIdx, setStrIdx] = useState(0);
  const [charIdx, setCharIdx] = useState(0);
  const [deleting, setDeleting] = useState(false);

  useEffect(() => {
    const current = strings[strIdx];
    let timeout;
    if (!deleting && charIdx < current.length) {
      timeout = setTimeout(() => setCharIdx((c) => c + 1), speed);
    } else if (!deleting && charIdx === current.length) {
      timeout = setTimeout(() => setDeleting(true), pause);
    } else if (deleting && charIdx > 0) {
      timeout = setTimeout(() => setCharIdx((c) => c - 1), speed / 2);
    } else {
      setDeleting(false);
      setStrIdx((i) => (i + 1) % strings.length);
    }
    setDisplay(current.slice(0, charIdx));
    return () => clearTimeout(timeout);
  }, [charIdx, deleting, strIdx, strings, speed, pause]);

  return display;
}

/* ════════════════════════════════════════
   SCROLL REVEAL HOOK
════════════════════════════════════════ */
function useScrollReveal() {
  useEffect(() => {
    const els = document.querySelectorAll('.reveal');
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            e.target.classList.add('visible');
            observer.unobserve(e.target);
          }
        });
      },
      { threshold: 0.1 }
    );
    els.forEach((el) => observer.observe(el));
    return () => observer.disconnect();
  }, []);
}

